    """Return the nth hexagonal number.

    Args:
        n: A non-negative integer.

    Returns:
        The nth hexagonal number.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 2 == 0:
        return hexagonal_num(n // 2) + hexagonal_num(n // 2 - 1)
    else:
        return hexagonal_num(n // 2) + hexagonal_num(n // 2 - 1)

