def tuple_str_int(tuple_str: str) -> tuple:
    """Convert a string representation of a tuple to an integer tuple.

    Args:
        tuple_str: A string representing a tuple in the format "tuple: int".

    Returns:
        A tuple (tuple_str_int, int) as integers.

    Raises:
        ValueError: If the tuple string is not in the correct format.
    """
    try:
        parts = tuple_str.split()
        if len(parts) != 2:
            raise ValueError("tuple_str must be in the format 'tuple: int'")
        return tuple(int(part) for part in parts)
    except ValueError as e:
        raise ValueError(f"Invalid tuple string: {tuple_str}") from e

