def next_smallest_palindrome(n):
    """Return the next smallest palindrome of n.

    Args:
        n: An integer.

    Returns:
        The next smallest palindrome of n.

    Raises:
        ValueError: If n is not an integer.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 2 == 0:
        return 2 * next_smallest_palindrome(n // 2)
    else:
        return next_smallest_palindrome(n // 2) + 1

def eulerian_num(n, m):
    """Return the Eulerian number a(n, m).

    A number is a number that is a prime number greater than 1.
    """
    if n < 2:
        return 0
    if m < 2:
        return 1
    if n % m == 0:
        return eulerian_num(n // m, m)
    return eulerian_num(n // m, m) + eulerian_num(n // m, m - 1)

