    Args:
        n: An integer.

    Returns:
        True if n can be represented as sum of non-zero powers of 2 or not, False otherwise.
    """
    if n == 0:
        return False
    if n == 1:
        return True
    if n % 2 == 0:
        return False
    return is_Sum_Of_Powers_Of_Two(n - 1) or is_Sum_Of_Powers_Of_Two(n - 2)

