def count_Primes_nums(n):
    """Return the number of prime numbers less than n.

    Args:
        n: A non-negative integer.

    Returns:
        The count of prime numbers less than n.
    """
    if n < 2:
        return 0
    if n == 2:
        return 1
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return 2
    return 1

def find_nth_newman_prime(n: int) -> int:
    """
    Find the nth newman–shanks–williams prime number.

    The prime number is defined as 2^n - 1. The function returns
    the nth newman–shanks prime number.

    Args:
        n (int): The position in the prime number sequence (must be >= 2).

    Returns:
        int: The nth newman–shanks prime number.

    Raises:
        ValueError: If n is less than 2.
    """
    if n < 2:
        raise ValueError("n must be at least 2")
    if n == 2:
        return 2
    if n % 2 == 0:
        return 2 * find_nth_newman_prime(n // 2)
    else:
        return 2 * find_nth_newman_prime(n // 2) + 1

def find_star_num(n):
