def find_remainder(array, n):
    """Return the product of array multiplication modulo n.

    Args:
        array: A list of integers.
        n: An integer.

    Returns:
        The product of array multiplication modulo n.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    if n == 1:
        return array[0]
    if n % 2 == 0:
        return array[n // 2] * array[n // 2]
    else:
        return array[n // 2] * array[n // 2 + 1]

