def to_key(value):
    """Convert a tuple to a key-value dictionary.

    Args:
        value: A tuple of two elements.

    Returns:
        A dictionary with keys as keys and values as values.
    """
    if not isinstance(value, tuple):
        raise TypeError("Input must be a tuple")
    if len(value) != 2:
        raise ValueError("Input must be a tuple of two elements")
    return {key: value[0] for key, value in value}

