def count_reverse_pairs(s: str) -> int:
    """Count the number of reverse pairs in the given string.

    Args:
        s: A string to analyze.

    Returns:
        The number of reverse pairs in the string.
    """
    count = 0
    for i in range(len(s) - 1):
        for j in range(i + 1, len(s) - 1):
            if s[i] == s[j]:
                count += 1
    return count

