def pair_wise(pairs):
    """Return a list of all consecutive pairs in `pairs`.

    Args:
        pairs: A list of integers.

    Returns:
        A list of tuples, each containing two integers.
    """
    result = []
    for i in range(len(pairs)):
        for j in range(i + 1, len(pairs)):
            if pairs[i] + pairs[j] == pairs[i] + pairs[j]:
                result.append((pairs[i], pairs[j]))
    return result

