def count_divisors(n):
    """Return True if n is a positive integer, False otherwise.

    A positive integer is a divisor of a positive integer.
    """
    if n <= 1:
        return False
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

