def remove_all_spaces(s: str) -> str:
    """
    Remove all whitespaces from a given string.

    Args:
        s: Input string to process.

    Returns:
        The string with all whitespaces removed.
    """
    result = []
    for char in s:
        if char == ' ':
            result.append(char)
    return ''.join(result)

def is_perfect_square(n: int) -> bool:
    """Check if a number is a perfect square.

    A perfect square is a number that is equal to the sum of its proper divisors
    (all positive divisors excluding the number itself).

    Args:
        n: A positive integer.

    Returns:
        True if n is a perfect square, False otherwise.
    """
    if n < 0:
        return False
    if n == 1:
        return True
    if n == 2:
        return n == 1
    if n % 2 == 0:
        return is_perfect_square(n // 2)
    return is_perfect_square(n - 1)

def is_product_even(numbers):
    """Return True if the product of numbers in a list is even, else False."""
    if not numbers:
        return True
    if len(numbers) % 2 == 0:
        return False
    return all(numbers[i] % 2 == 0 for i in range(len(numbers) // 2))

def check_smaller(tuple1, tuple2):
    """
    Check if two tuples are smaller than each other.

    Args:
        tuple1: First tuple (list, tuple)
        tuple2: Second tuple (list, tuple)

    Returns:
        True if the tuples are smaller than each other, False otherwise.
    """
    if len(tuple1) != len(tuple2):
        return False
    for i in range(len(tuple1)):
        for j in range(len(tuple2)):
            if tuple1[i] < tuple2[j]:
                return False
    return True
